33	using Scalar.AspNetCore;
34	using CorsOptions = Kanban.Api.Options.CorsOptions;
35	
36	var builder = WebApplication.CreateBuilder(args);
37	
38	// ── Options — fail at boot if configuration is missing ────────────────────────
39	
40	builder.Services.AddOptions<GoogleAuthOptions>()
41	    .Bind(builder.Configuration.GetSection(GoogleAuthOptions.SectionName))
42	    .ValidateDataAnnotations()
43	    .ValidateOnStart();
44	
45	builder.Services.AddOptions<SeedOptions>()
46	    .Bind(builder.Configuration.GetSection(SeedOptions.SectionName))
47	    .ValidateDataAnnotations()
48	    .ValidateOnStart();
49	
50	builder.Services.AddOptions<CorsOptions>()
51	    .Bind(builder.Configuration.GetSection(CorsOptions.SectionName))
52	    .ValidateDataAnnotations()
53	    .ValidateOnStart();
54	
55	builder.Services.AddOptions<ConnectionStringOptions>()
56	    .Bind(builder.Configuration.GetSection(ConnectionStringOptions.SectionName))
57	    .ValidateDataAnnotations()
58	    .ValidateOnStart();
59	
60	// ── Database ──────────────────────────────────────────────────────────────────
61	
62	DapperConfiguration.RegisterTypeHandlers();
63	
64	// Resolve the connection string lazily from IOptions so that WebApplicationFactory
65	// configuration overrides (applied after builder services are registered) are honoured.
66	builder.Services.AddScoped<IDbConnection>(sp =>
67	{
68	    var opts = sp.GetRequiredService<IOptions<ConnectionStringOptions>>().Value;
69	    var conn = new SqliteConnection(opts.Kanban);
70	    conn.Open();
71	    using var cmd = conn.CreateCommand();
72	    cmd.CommandText = "PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;";
73	    cmd.ExecuteNonQuery();
74	    return conn;
75	});
76	
77	// ── Exception Handling ────────────────────────────────────────────────────────
78	
79	builder.Services.AddProblemDetails(options =>
80	{
81	    options.CustomizeProblemDetails = ctx =>
82	    {
83	        ctx.ProblemDetails.Extensions["traceId"] = Activity.Current?.Id;
84	        if (ctx.HttpContext.Response.StatusCode == StatusCodes.Status403Forbidden
85	            && !ctx.ProblemDetails.Extensions.ContainsKey("code"))
86	        {
87	            ctx.ProblemDetails.Title = "You are not registered to use this application.";
88	            ctx.ProblemDetails.Extensions["code"] = "user.not_registered";
89	        }
90	    };
91	});
92	builder.Services.AddExceptionHandler<DomainExceptionHandler>();
93	builder.Services.AddExceptionHandler<InfrastructureExceptionHandler>();
94	builder.Services.AddExceptionHandler<FallbackExceptionHandler>();
95	
96	// ── CORS ──────────────────────────────────────────────────────────────────────
97	
98	builder.Services.AddCors(options =>
99	    options.AddPolicy("KanbanWebApp", policy =>
100	        policy
101	            .WithOrigins(
102	                builder.Configuration
103	                    .GetSection("Cors:AllowedOrigins")
104	                    .Get<string[]>() ?? [])
105	            .WithMethods("GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS")
106	            .AllowAnyHeader()
107	            .WithExposedHeaders("X-Correlation-Id", "api-supported-versions")));
108	
109	// ── Authentication & Authorization ───────────────────────────────────────────
110	
111	builder.Services.AddScoped<ICurrentUserService, CurrentUserService>();
112	builder.Services.AddScoped<IAuthService, AuthService>();
113	builder.Services.AddScoped<IInvitationService, InvitationService>();
114	builder.Services.AddSingleton<IDbConnectionFactory, SqliteConnectionFactory>();
115	builder.Services.AddScoped<GoogleIdentityAdapter>();
116	builder.Services.AddScoped<IUserRepository, UserRepository>();
117	builder.Services.AddScoped<IAuthEventRepository, AuthEventRepository>();
118	builder.Services.AddScoped<IInvitationRepository, InvitationRepository>();
119	builder.Services.AddScoped<IBoardRepository, BoardRepository>();
120	builder.Services.AddScoped<ILaneRepository, LaneRepository>();
121	builder.Services.AddScoped<ICardRepository, CardRepository>();
122	builder.Services.AddScoped<IBoardMemberRepository, BoardMemberRepository>();
123	builder.Services.AddValidatorsFromAssemblyContaining<IssueInviteRequestValidator>();
124	builder.Services.AddHttpContextAccessor();
125	builder.Services.AddScoped<IAuthorizationHandler, RegisteredUserHandler>();
126	builder.Services.AddScoped<IAuthorizationHandler, BoardAuthorizationHandler>();
127	builder.Services.AddScoped<IBoardService, BoardService>();
128	builder.Services.AddScoped<ILaneService, LaneService>();
129	builder.Services.AddScoped<ICardService, CardService>();
130	
131	builder.Services.AddAuthentication(options =>
132	    {
133	        options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
134	        options.DefaultChallengeScheme = GoogleDefaults.AuthenticationScheme;
135	    })
136	    .AddCookie(options =>
137	    {
138	        options.LoginPath = "/api/v1/auth/signin";
139	        options.Events.OnRedirectToLogin = ctx =>
140	        {
141	            ctx.Response.StatusCode = StatusCodes.Status401Unauthorized;
142	            return Task.CompletedTask;
143	        };
144	        options.Events.OnRedirectToAccessDenied = ctx =>
145	        {
146	            ctx.Response.StatusCode = StatusCodes.Status403Forbidden;
147	            return Task.CompletedTask;
148	        };
149	    })
150	    .AddGoogle(options =>
151	    {
152	        var googleOpts = builder.Configuration
153	            .GetSection(GoogleAuthOptions.SectionName)
154	            .Get<GoogleAuthOptions>()!;
155	        options.ClientId = googleOpts.ClientId;
156	        options.ClientSecret = googleOpts.ClientSecret;
157	
158	        // ASP.NET Core's default ClaimActions remap "sub" → ClaimTypes.NameIdentifier
159	        // (a long URN). GoogleIdentityAdapter expects the raw OIDC claim names, so we
160	        // clear the defaults and map only the three fields the adapter actually reads.
161	        options.ClaimActions.Clear();
162	        options.ClaimActions.MapJsonKey("sub", "sub");
163	        options.ClaimActions.MapJsonKey("email", "email");
164	        options.ClaimActions.MapJsonKey("name", "name");
165	
166	        options.Events.OnTicketReceived = async ctx =>
167	        {
168	            var adapter = ctx.HttpContext.RequestServices
169	                .GetRequiredService<GoogleIdentityAdapter>();
170	            var authService = ctx.HttpContext.RequestServices
171	                .GetRequiredService<IAuthService>();
172	
173	            if (ctx.Principal is not null)
174	            {
175	                var identity = adapter.Extract(ctx.Principal);
176	                var claimsIdentity = ctx.Principal.Identity as System.Security.Claims.ClaimsIdentity;
177	                if (claimsIdentity is not null)
178	                {
179	                    await authService.HandleSignInAsync(
180	                        identity.Sub,
181	                        identity.Email,
182	                        claimsIdentity,
183	                        ctx.HttpContext.RequestAborted);
184	                }
185	            }
186	        };
187	    });
188	
189	builder.Services.AddAuthorizationBuilder()
190	    .AddPolicy("RegisteredUser", policy => policy
191	        .RequireAuthenticatedUser()
192	        .AddRequirements(new RegisteredUserRequirement()))
193	    .AddPolicy("Admin", policy => policy
194	        .RequireAuthenticatedUser()
195	        .RequireClaim("system_role", "admin"));
196	
197	// ── API Versioning ────────────────────────────────────────────────────────────
198	
199	builder.Services.AddApiVersioning(options =>
200	{
201	    options.DefaultApiVersion = new ApiVersion(1, 0);
202	    options.AssumeDefaultVersionWhenUnspecified = true;
203	    options.ReportApiVersions = true;
204	});
205	
206	// ── OpenAPI — development only ────────────────────────────────────────────────
207	
208	if (builder.Environment.IsDevelopment())
209	    builder.Services.AddOpenApi();
210	
211	// ── Health Checks ─────────────────────────────────────────────────────────────
212	
213	builder.Services.AddHealthChecks()
214	    .AddCheck("self", () => Microsoft.Extensions.Diagnostics.HealthChecks.HealthCheckResult.Healthy(), tags: ["live"])
215	    .AddCheck<DatabaseHealthCheck>("database", tags: ["ready"]);
216	
217	// ── Rate Limiting ─────────────────────────────────────────────────────────────
218	
219	builder.Services.AddRateLimiter(opts =>
220	{
221	    opts.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
222	    opts.OnRejected = async (ctx, _) =>
223	    {
224	        ctx.HttpContext.Response.Headers.RetryAfter = "60";
225	        await Results.Problem(
226	                title: "Too many requests",
227	                statusCode: StatusCodes.Status429TooManyRequests,
228	                detail: "Please retry after the Retry-After interval.")
229	            .ExecuteAsync(ctx.HttpContext);
230	    };
231	
232	    opts.AddPolicy("anonymous", httpContext =>
233	        RateLimitPartition.GetFixedWindowLimiter(
234	            partitionKey: httpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown",
235	            factory: _ => new System.Threading.RateLimiting.FixedWindowRateLimiterOptions
236	            {
237	                PermitLimit = 10,
238	                Window = TimeSpan.FromMinutes(1),
239	            }));
240	
241	    opts.AddSlidingWindowLimiter("authenticated", o =>
242	    {
243	        o.PermitLimit = 100;
244	        o.Window = TimeSpan.FromMinutes(1);
245	        o.SegmentsPerWindow = 6;
